message.content:
{
  "title": "The Ruined City Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone gates loom under a gray sky, rusted portcullis half-raised, old royal banners tattered in the wind.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople huddle in a market square.",
      "visual_description": "A cracked fountain surrounded by fearful villagers clutching meager belongings, shadows of patrols visible in nearby alleys.",
      "characters": ["Townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "The patrol questions the party's intent.",
      "visual_description": "Armored soldiers in rusted plate armor block a cobblestone street, their captain pointing a gauntleted finger at the party.",
      "characters": ["Elara", "Kael", "Mira", "Captain Aldric", "Patrol Soldier"]
    },
    {
      "scene_number": 4,
      "caption": "The party bribes or sneaks past the patrol.",
      "visual_description": "Kael tosses a pouch of coins to the captain while Mira gestures subtly to a side alley, Elara watches the rooftops.",
      "characters": ["Elara", "Kael", "Mira", "Captain Aldric"]
    },
    {
      "scene_number": 5,
      "caption": "A cursed tower looms ahead, covered in thorns.",
      "visual_description": "A twisted spire of black stone wrapped in glowing thorn vines, a single lit window at the top like an eye.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 6,
      "caption": "Inside the tower, a magic door blocks the path.",
      "visual_description": "A massive stone door carved with runes that pulse with blue light, set in a circular chamber with a mosaic floor.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 7,
      "caption": "Kael attempts to pick the door's lock but triggers a trap.",
      "visual_description": "A spray of arcane darts shoots from the walls as Kael recoils, Elara throws up a shield, Mira dodges behind a pillar.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 8,
      "caption": "Elara deciphers the riddle on the door.",
      "visual_description": "Elara traces the glowing runes with her finger while Kael and Mira guard the staircase behind them.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 9,
      "caption": "The door opens to reveal a treasure room full of illusions.",
      "visual_description": "Piles of gold and jewels shimmer, but shadows twist at the edges, revealing false treasures and hidden pitfalls.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 10,
      "caption": "A rumor of dragons is confirmed by a wounded scout.",
      "visual_description": "A bloodied scout leans against a wall in a ruined chapel, pointing toward a distant mountain, a dragon scale clutched in his hand.",
      "characters": ["Elara", "Kael", "Mira", "Wounded Scout"]
    },
    {
      "scene_number": 11,
      "caption": "The party navigates the abandoned royal palace.",
      "visual_description": "Shattered chandeliers and moth-eaten tapestries line a grand hall, the throne cracked and overturned at the far end.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 12,
      "caption": "They find the captive in a dungeon cell.",
      "visual_description": "A dark cell with iron bars, a person in rags sits on a stone floor, a faint magical glow from a manacle on their wrist.",
      "characters": ["Elara", "Kael", "Mira", "Captive Soran"]
    },
    {
      "scene_number": 13,
      "caption": "Soran is freed but weak from magical suppression.",
      "visual_description": "Soran stumbles out of the cell, the broken manacle falling away, Elara supports him as Kael checks the corridor.",
      "characters": ["Elara", "Kael", "Mira", "Captive Soran"]
    },
    {
      "scene_number": 14,
      "caption": "Alarms sound as patrols converge on the dungeon.",
      "visual_description": "Horn blasts echo, the clatter of armored boots on stone stairs, torches flicker from multiple corridors.",
      "characters": ["Elara", "Kael", "Mira", "Captive Soran"]
    },
    {
      "scene_number": 15,
      "caption": "The party fights through a squad of guards.",
      "visual_description": "Kael swings a sword at armored guards, Elara casts a blinding light, Mira fires arrows from a balcony, Soran staggers behind cover.",
      "characters": ["Elara", "Kael", "Mira", "Captive Soran", "Patrol Soldier"]
    },
    {
      "scene_number": 16,
      "caption": "They escape into the ruined streets under moonlight.",
      "visual_description": "Moonbeams pierce broken roofs, casting long shadows as the party runs through rubble-strewn alleys, distant torchlight behind them.",
      "characters": ["Elara", "Kael", "Mira", "Captive Soran"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge to freedom is guarded by a last patrol.",
      "visual_description": "A narrow stone bridge over a chasm, with a line of archers and a captain blocking the far end, torches lighting the scene.",
      "characters": ["Elara", "Kael", "Mira", "Captive Soran", "Captain Aldric", "Patrol Soldier"]
    },
    {
      "scene_number": 18,
      "caption": "The party crosses the bridge and escapes the city.",
      "visual_description": "The bridge collapses behind them as they reach the far side, the ruined city silhouetted against the sunrise, banners aflame.",
      "characters": ["Elara", "Kael", "Mira", "Captive Soran"]
    }
  ]
}

